package io.lumine.mythic.lib.api.event.mitigation;import io.lumine.mythic.lib.api.player.MMOPlayerData;import io.lumine.mythic.lib.damage.AttackMetadata;public class PlayerParryEvent{private final MMOPlayerData player;private final AttackMetadata attack;private boolean cancelled;public PlayerParryEvent(MMOPlayerData player,AttackMetadata attack){this.player=player;this.attack=attack;}public MMOPlayerData getPlayerData(){return player;}public AttackMetadata getAttack(){return attack;}public boolean isCancelled(){return cancelled;}public void setCancelled(boolean c){cancelled=c;}}